 public record PlanUpdate(@NotNull Long recordVersion,@NotBlank@Size(max=200)String title,@NotBlank@Size(max=4000)String objectives,@NotNull LocalDate periodStart,@NotNull LocalDate periodEnd,@NotNull@DecimalMin("0")BigDecimal estimatedCost,@NotBlank@Size(max=500)String fundingSource){}
