 public record ProgramSourceResponse(String id,String planSourceId,String sourceFingerprint,String developmentObjective,String successMeasure,int displayOrder){}
 public record ProgramResponse(String id,String seriesId,int programVersion,String supersedesId,String planId,int planVersion,String planFingerprint,String code,String title,String interventionVersionId,String interventionFingerprint,String evaluationFrameworkVersionId,String evaluationFingerprint,String intendedOutcomes,String deliveryStrategy,LocalDate scheduleStart,LocalDate scheduleEnd,BigDecimal estimatedHours,BigDecimal estimatedCost,String fundingSource,Long accountableEmployeeId,String accountableEmployeeNo,String accountableName,Long accountableAppointmentId,String accountableFingerprint,String status,int contentRevision,long recordVersion,String submittedBy,Instant submittedAt,String approvedBy,Instant approvedAt,List<ProgramSourceResponse>sources){}
 public record OfferingCreate(@NotBlank String programId,@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@NotNull LdInterventionVersion.Modality modality,@NotBlank@Size(max=1000)String venueOrPlatform,@Min(1)int capacity,String providerId,@NotNull@DecimalMin("0")BigDecimal approvedBudget,@NotBlank@Size(max=500)String fundingSource,@NotBlank@Pattern(regexp="[A-Za-z]{3}")String currencyCode,Instant registrationOpen,Instant registrationClose){}
 public record OfferingUpdate(@NotNull Long recordVersion,@NotBlank@Size(max=80)String code,@NotBlank@Size(max=200)String title,@NotNull LdInterventionVersion.Modality modality,@NotBlank@Size(max=1000)String venueOrPlatform,@Min(1)int capacity,@NotNull@DecimalMin("0")BigDecimal approvedBudget,@NotBlank@Size(max=500)String fundingSource,@NotBlank@Pattern(regexp="[A-Za-z]{3}")String currencyCode,Instant registrationOpen,Instant registrationClose){}
 public record SessionInput(@NotBlank@Size(max=200)String title,@NotNull OffsetDateTime startsAt,@NotNull OffsetDateTime endsAt,@NotBlank@Size(max=1000)String venueOrPlatform,@NotNull@DecimalMin(value="0",inclusive=false)BigDecimal creditedHours,@Min(1)int displayOrder){}
